def is_k_colorable(graph, k):
    n = len(graph)
    colors = [-1]*n
    def backtrack(v):
        if v == n:
            return True
        used = [False]*k
        for u in graph[v]:
            if colors[u] != -1:
                used[colors[u]] = True
        for c in range(k):
            if not used[c]:
                colors[v] = c
                if backtrack(v+1):
                    return True
                colors[v] = -1
        return False
    return backtrack(0)
