def stoer_wagner(graph):
    n = len(graph)
    vertices = list(range(n))
    min_cut = float('inf')
    while len(vertices) > 1:
        A = [vertices[0]]
        S = set(A)
        w = [0]*n
        for v in vertices:
            if v != A[0]:
                w[v] = graph[A[0]][v]
        while set(vertices) - S:
            u = max((v for v in vertices if v not in S), key=lambda x: w[x])
            S.add(u)
            A.append(u)
            for v in vertices:
                if v not in S:
                    w[v] += graph[u][v]
        s, t = A[-1], A[-2]
        cut_weight = sum(graph[t][v] for v in vertices if v != t)
        min_cut = min(min_cut, cut_weight)
        for v in vertices:
            if v != t:
                graph[s][v] += graph[t][v]
                graph[v][s] += graph[v][t]
        vertices.remove(t)
    return min_cut
