def astar(graph, h, s, t):
    import heapq
    open_set = [(h[s], 0, s)]
    g_score = {s:0}
    while open_set:
        f, g, u = heapq.heappop(open_set)
        if u == t:
            return g
        if g > g_score.get(u, float('inf')):
            continue
        for v, w in graph[u]:
            ng = g + w
            if ng < g_score.get(v, float('inf')):
                g_score[v] = ng
                heapq.heappush(open_set, (ng + h[v], ng, v))
    return -1
