def hopcroft_karp(graph, U, V):
    pair_U = {u:None for u in U}
    pair_V = {v:None for v in V}
    dist = {}
    def bfs():
        q = []
        for u in U:
            if pair_U[u] is None:
                dist[u] = 0
                q.append(u)
            else:
                dist[u] = float('inf')
        dist[None] = float('inf')
        for u in q:
            if dist[u] < dist[None]:
                for v in graph[u]:
                    if dist[pair_V[v]] == float('inf'):
                        dist[pair_V[v]] = dist[u] + 1
                        q.append(pair_V[v])
        return dist[None] != float('inf')
    def dfs(u):
        if u is not None:
            for v in graph[u]:
                if dist[pair_V[v]] == dist[u] + 1:
                    if dfs(pair_V[v]):
                        pair_V[v] = u
                        pair_U[u] = v
                        return True
            dist[u] = float('inf')
            return False
        return True
    matching = 0
    while bfs():
        for u in U:
            if pair_U[u] is None:
                if dfs(u):
                    matching += 1
    return matching
