def centroid_decomposition(tree, n):
    size = [0]*n
    vis = [False]*n
    def get_size(u, p):
        size[u] = 1
        for v in tree[u]:
            if v != p and not vis[v]:
                size[u] += get_size(v, u)
        return size[u]
    def get_centroid(u, p, total):
        for v in tree[u]:
            if v != p and not vis[v] and size[v] > total//2:
                return get_centroid(v, u, total)
        return u
    def decompose(u):
        total = get_size(u, -1)
        c = get_centroid(u, -1, total)
        vis[c] = True
        res = [c]
        for v in tree[c]:
            if not vis[v]:
                res.extend(decompose(v))
        return res
    return decompose(0)

