def connected_components_parallel(edges, n):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry
    for u, v in edges:
        union(u, v)
    roots = set(find(i) for i in range(n))
    return len(roots)

