def greedy_matroid(elements, weights, independent_check):
    sorted_elements = sorted(zip(elements, weights), key=lambda x: -x[1])
    independent_set = []
    for e, w in sorted_elements:
        if independent_check(independent_set + [e]):
            independent_set.append(e)
