                            pass
            dp[u][mask] = bin(mask).count('1')
        for v in tree_decomp[u]:
            if v != p:
                dfs(v, u)
                new_dp = {}
                for m1 in dp[u]:
                    for m2 in dp[v]:
                        m = m1 | m2
