def max_flow_min_cost_cycle_cancel(C, cost, s, t):
    n = len(C)
    F = [[0]*n for _ in range(n)]
    flow = 0
    total_cost = 0
    def find_augmenting_path():
        dist = [float('inf')]*n
        parent = [-1]*n
        dist[s] = 0
        in_queue = [False]*n
        q = [s]
        in_queue[s] = True
        while q:
            u = q.pop(0)
            in_queue[u] = False
            for v in range(n):
                if C[u][v] - F[u][v] > 0 and dist[v] > dist[u] + cost[u][v]:
                    dist[v] = dist[u] + cost[u][v]
                    parent[v] = u
                    if not in_queue[v]:
                        q.append(v)
                        in_queue[v] = True
        return parent, parent[t] != -1
    def cancel_cycles():
        for _ in range(n*2):
            updated = False
            for u in range(n):
                for v in range(n):
                    if F[u][v] > 0:
                        for w in range(n):
                            if F[v][w] > 0 and cost[u][v] + cost[v][w] < cost[u][w]:
                                return True
            if not updated:
                break
        return False
    parent, ok = find_augmenting_path()
    if ok:
        v = t
        f = float('inf')
        while v != s:
            u = parent[v]
            f = min(f, C[u][v] - F[u][v])
            v = u
        v = t
        while v != s:
            u = parent[v]
            F[u][v] += f
            F[v][u] -= f
            total_cost += f * cost[u][v]
            v = u
        flow = f
    return flow, total_cost
