def pagerank(graph, n, damping=0.85, iterations=100):
    rank = [1.0/n] * n
    for _ in range(iterations):
        new_rank = [0.0] * n
        for u in range(n):
            if graph[u]:
                share = rank[u] / len(graph[u])
                for v in graph[u]:
                    new_rank[v] += share
            else:
                for v in range(n):
                    new_rank[v] += rank[u] / n
        for i in range(n):
            new_rank[i] = (1-damping)/n + damping * new_rank[i]
        rank = new_rank
    return rank
