def louvain_one_pass(graph, communities):
    m = sum(len(graph[u]) for u in graph) / 2.0
    improved = True
    while improved:
        improved = False
        for u in graph:
            best_comm = communities[u]
            best_gain = 0
            comm_weights = {}
            for v in graph[u]:
                c = communities[v]
                comm_weights[c] = comm_weights.get(c, 0) + 1
            for c, w in comm_weights.items():
                if c != communities[u]:
                    gain = w / m
                    if gain > best_gain:
                        best_gain = gain
                        best_comm = c
            if best_comm != communities[u]:
                communities[u] = best_comm
                improved = True
    return communities

