def streaming_connected_components(stream, n):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x
    for u, v in stream:
        ru, rv = find(u), find(v)
        if ru != rv:
            parent[ru] = rv
    roots = set(find(i) for i in range(n))
    return len(roots)
