def greedy_spanner(graph, k):
    edges = []
    for u in graph:
        for v in graph[u]:
            if u < v:
                edges.append((u,v,graph[u][v]))
    edges.sort(key=lambda x:x[2])
    spanner = {u:{} for u in graph}
    dist = {u:{v:float('inf') for v in graph} for u in graph}
    for u in graph:
        dist[u][u] = 0
    for u,v,w in edges:
        if dist[u][v] > k * w:
            spanner[u][v] = w
            spanner[v][u] = w
            for x in graph:
                for y in graph:
                    if dist[x][u] + w + dist[v][y] < dist[x][y]:
                        dist[x][y] = dist[x][u] + w + dist[v][y]
    return spanner
