class EulerTourTree:
    def __init__(self, n):
        self.n = n
        self.adj = [[] for _ in range(n)]
        self.visited = set()

    def add_edge(self, u, v):
        self.adj[u].append(v)
        self.adj[v].append(u)

    def euler_tour(self, start):
        tour = []
        def dfs(u, p):
            tour.append(u)
            for v in self.adj[u]:
                if v != p:
                    dfs(v, u)
            tour.append(u)
            return tour
        return dfs(start, -1)

