import random
def karger_min_cut(edges, n):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx != ry:
            parent[rx] = ry

    while n > 2:
        i = random.randint(0, len(edges)-1)
        u, v = edges[i]
        if find(u) != find(v):
            union(u, v)
            n -= 1

    cut = 0
    for u, v in edges:
        if find(u) != find(v):
            cut += 1
    return cut

