def christofides_tsp(dist, n):
    import heapq
    def prim():
        visited = [False]*n
        mst = [[] for _ in range(n)]
        pq = [(0, 0, -1)]
        while pq:
            w, u, p = heapq.heappop(pq)
            if visited[u]: continue
            visited[u] = True
            if p != -1:
                mst[u].append(p)
                mst[p].append(u)
            for v in range(n):
                if not visited[v]:
                    heapq.heappush(pq, (dist[u][v], v, u))
        return mst
    mst = prim()
    odd = [i for i in range(n) if len(mst[i]) % 2 == 1]
    return len(odd)

