def treewidth_ub(graph):
    n = len(graph)
    order = sorted(range(n), key=lambda x: len(graph[x]))
    tw = 0
    eliminated = set()
    for v in order:
        neighbors = [u for u in graph[v] if u not in eliminated]
        tw = max(tw, len(neighbors))
        for i in range(len(neighbors)):
            for j in range(i+1, len(neighbors)):
                if neighbors[j] not in graph[neighbors[i]]:
                    graph[neighbors[i]].add(neighbors[j])
                    graph[neighbors[j]].add(neighbors[i])
        eliminated.add(v)
    return tw

