def color_coding_path(graph, k):
    n = len(graph)
    colors = [random.randint(0, k-1) for _ in range(n)]
    dp = [[False]*n for _ in range(1<<k)]
    for i in range(n):
        dp[1<<colors[i]][i] = True
    for mask in range(1<<k):
        for u in range(n):
            if dp[mask][u]:
                for v in graph[u]:
                    c = colors[v]
                    if not (mask & (1<<c)):
                        dp[mask | (1<<c)][v] = True
    for mask in range(1<<k):
        if bin(mask).count('1') == k:
            for u in range(n):
                if dp[mask][u]:
                    return True
    return False

