def tutte_polynomial(graph, x, y):
    if not graph:
        return 1
    u = next(iter(graph))
    if not graph[u]:
        del graph[u]
        return y * tutte_polynomial(graph, x, y)
    v = graph[u].pop()
    graph[v].remove(u)
    graph_copy = {k:set(graph[k]) for k in graph}
    if u in graph_copy and v in graph_copy:
        graph_copy[u].update(graph_copy[v])
        for w in graph_copy[v]:
            graph_copy[w].discard(v)
            graph_copy[w].add(u)
        del graph_copy[v]
    T1 = tutte_polynomial({k:set(graph[k]) for k in graph if graph[k]}, x, y)
    T2 = tutte_polynomial(graph_copy, x, y)
    return T1 + T2

