def greedy_mis_local(graph):
    n = len(graph)
    in_mis = [False]*n
    removed = [False]*n
    changed = True
    while changed:
        changed = False
        for u in range(n):
            if not removed[u] and not in_mis[u]:
                can_add = True
                for v in graph[u]:
                    if in_mis[v]:
                        can_add = False
                        break
                if can_add:
                    in_mis[u] = True
                    removed[u] = True
                    for v in graph[u]:
                        removed[v] = True
                    changed = True
    return sum(in_mis)

